class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG = -10**18
        prev = [0] * (n + 1)  # row for 0 subarrays: f(i, 0) = 0

        for _ in range(k):
            curr = [NEG] * (n + 1)
            best = NEG
            t = 0
            for i in range(n + 1):
                # Add all t <= i - m (last subarray [t, i) has length >= m)
                limit = i - m
                while t <= limit:
                    if prev[t] != NEG:
                        v = prev[t] - prefix[t]
                        if v > best:
                            best = v
                    t += 1
                # carry: don't use a subarray ending at i
                val = curr[i - 1] if i > 0 else NEG
                # use subarray ending at i
                if best != NEG:
                    cand = prefix[i] + best
                    if cand > val:
                        val = cand
                curr[i] = val
            prev = curr

        return prev[n]

