class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # Total number of alternating permutations
        if n % 2 == 0:
            total = 2 * fact[n // 2] * fact[n // 2]
        else:
            total = fact[(n + 1) // 2] * fact[(n - 1) // 2]

        if k > total:
            return []

        used = [False] * (n + 1)
        res = []
        prev_parity = -1          # 1 = odd, 0 = even
        rem_odd = (n + 1) // 2
        rem_even = n // 2

        for pos in range(n):
            chosen = -1
            for v in range(1, n + 1):
                if used[v]:
                    continue
                p = v & 1
                if pos > 0 and p == prev_parity:
                    continue                     # must alternate
                if pos == 0 and n % 2 == 1 and p == 0:
                    continue                     # odd n must start with odd
                ro = rem_odd - (1 if p == 1 else 0)
                re_ = rem_even - (1 if p == 0 else 0)
                cnt = fact[ro] * fact[re_]
                if k <= cnt:
                    chosen = v
                    break
                k -= cnt
            used[chosen] = True
            res.append(chosen)
            p = chosen & 1
            if p == 1:
                rem_odd -= 1
            else:
                rem_even -= 1
            prev_parity = p

        return res
